function r(n,o){n.replaceChildren();const c=n.createTHead().insertRow();for(const e of["时间","模型","状态","耗时（ms）"]){const t=document.createElement("th");t.textContent=e,c.append(t)}const s=n.createTBody();for(const e of o){const t=s.insertRow();for(const l of[e.started_at,e.model,e.status,e.latency_ms])t.insertCell().textContent=String(l??"—")}if(!o.length){const e=s.insertRow().insertCell();e.colSpan=4,e.textContent="暂无采集记录"}}export{r as renderRequestLogs};
